import 'package:flutter/material.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';import 'package:get/get.dart';import '../../../../utils/themes/light_theme.dart';import '../../card_controller/card_controller.dart';class PayChoose extends StatelessWidget {  const PayChoose({Key? key}) : super(key: key);  @override  Widget build(BuildContext context) {    return GetBuilder<CardController>(builder: (logic) {      return Container(        padding: EdgeInsets.all(16),        height: 275.h,        decoration: BoxDecoration(            borderRadius: BorderRadius.only(                topLeft: Radius.circular(25), topRight: Radius.circular(25)),            color: Colors.white),        child: Column(          crossAxisAlignment: CrossAxisAlignment.start,          mainAxisAlignment: MainAxisAlignment.start,          children: [            Text(              "optionPay".tr,              style: TextStyle(fontSize: 18.sp),            ),            SizedBox(              height: 15.h,            ),            Column(              children: [                Row(                  mainAxisAlignment: MainAxisAlignment.start,                  children: [                    Radio(                      materialTapTargetSize: MaterialTapTargetSize.shrinkWrap,                      visualDensity: const VisualDensity(                          horizontal: VisualDensity.minimumDensity,                          vertical: VisualDensity.minimumDensity),                      value: 'visa',                      groupValue: logic.groupPay,                      onChanged: (c) {                        logic.changePayValue(c.toString());                      },                      activeColor: logic.groupPay == "visa"                          ? HexaColor.fromHexa('#00A19B')                          : HexaColor.fromHexa('#999999'),                    ),                    SizedBox(                      width: 5.w,                    ),                    GestureDetector(                      onTap: () {                        logic.changePayValue('visa');                      },                      child: Text(                        'visa'.tr,                        style: TextStyle(                          fontSize: 16.sp,                          color: logic.groupPay == "visa"                              ? HexaColor.fromHexa('#00A19B')                              : HexaColor.fromHexa('#999999'),                        ),                      ),                    ),                  ],                ),                SizedBox(                  height: 15.w,                ),                Row(                  children: [                    Radio(                      materialTapTargetSize: MaterialTapTargetSize.shrinkWrap,                      visualDensity: const VisualDensity(                          horizontal: VisualDensity.minimumDensity,                          vertical: VisualDensity.minimumDensity),                      value: 'Benefit Pay',                      groupValue: logic.groupPay,                      onChanged: (c) {                        logic.changePayValue('Benefit Pay');                      },                      activeColor: logic.groupPay == "Benefit Pay"                          ? HexaColor.fromHexa('#00A19B')                          : HexaColor.fromHexa('#999999'),                    ),                    SizedBox(                      width: 5.w,                    ),                    GestureDetector(                      onTap: () {                        logic.changePayValue('Benefit Pay');                        logic.update();                      },                      child: Text(                        'Benefit Pay'.tr,                        style: TextStyle(                            color: logic.groupPay == "Benefit Pay"                                ? HexaColor.fromHexa('#00A19B')                                : HexaColor.fromHexa('#999999')),                      ),                    ),                  ],                ),                SizedBox(                  height: 15.w,                ),                Row(                  mainAxisAlignment: MainAxisAlignment.start,                  children: [                    Radio(                      materialTapTargetSize: MaterialTapTargetSize.shrinkWrap,                      visualDensity: const VisualDensity(                          horizontal: VisualDensity.minimumDensity,                          vertical: VisualDensity.minimumDensity),                      value: 'Other',                      groupValue: logic.groupPay,                      onChanged: (c) {                        logic.changePayValue(c.toString());                      },                      activeColor: logic.groupPay == "Other"                          ? HexaColor.fromHexa('#00A19B')                          : HexaColor.fromHexa('#999999'),                    ),                    SizedBox(                      width: 5.w,                    ),                    GestureDetector(                      onTap: () {                        logic.changePayValue('Other');                      },                      child: Text(                        'Other'.tr,                        style: TextStyle(                          fontSize: 16.sp,                          color: logic.groupPay == "Other"                              ? HexaColor.fromHexa('#00A19B')                              : HexaColor.fromHexa('#999999'),                        ),                      ),                    ),                  ],                ),              ],            ),            SizedBox(              height: 20.h,            ),            SizedBox(              height: 44.h,              width: double.infinity,              child: ElevatedButton(                onPressed: () {                  if (logic.groupValue == "familyCard") {                    logic.makefamily(context);                  }                  if (logic.groupValue == "onlyCard") {                    logic.makeSingleCard(context);                  }                },                child: Text("confirmOrder".tr),              ),            ),            SizedBox(              height: 10.h,            ),          ],        ),      );    });  }}